# shapes.py
class Shape(ABC):
    @abstractmethod
    def area(self): ...
class Circle(Shape):
    def __init__(self, r): self.r = r
    def area(self): return 3.141592653589793 * self.r * self.r
class Rect(Shape):
    def __init__(self, w, h): self.w=w; self.h=h
    def area(self): return self.w*self.h
# other.py
class Tri(Shape):
    def __init__(self, b, h): self.b=b; self.h=h
    def area(self): return 0.5*self.b*self.h
t = Tri(3,4)
result = t.area()

